UPDATE video


        like_count = like_count + #{count}


        collect_count = collect_count + #{count}


        watch_count = watch_count + #{count}


WHERE id = #{videoId}

mapper.select:
SELECT DISTINCT v.*
FROM video v
JOIN video_tag_relation vtr ON v.id = vtr.video_id
WHERE 1=1

    AND vtr.tag_id IN

        #{tagItem}







    AND (
    v.create_time  <  #{cursorTime}
    OR (v.create_time = #{cursorTime} AND v.id  <  #{cursorId})
    )


ORDER BY v.create_time DESC, v.id DESC
LIMIT #{size}

SELECT v.* FROM video v INNER JOIN user_action ua ON v.id = ua.video_id
WHERE
ua.user_id = #{userId}
AND ua.type = #{type}
ORDER BY
ua.create_time DESC

SELECT * FROM video WHERE user_id IN
#{item}
ORDER BY create_time DESC
